import { claim_start_ticket } from "@/graphql/mutations.js";
import { API, graphqlOperation } from "aws-amplify";
export default {
  props: {
    resumeTicketDialog: Boolean,
    rowInfo: Object
  },
  data() {
    return {
      loading2: false
    };
  },
  methods: {
    close_dialog() {
      this.$emit("clicked", 0);
    },
    fetch_value(val) {
      const d = new Date(parseInt(val * 1000));
      var date = d.getDate().toLocaleString();
      var month = (d.getMonth() + 1).toLocaleString();
      var year = d.getFullYear();
      var dateValue = (+date <= 9 ? "0" + date : date) + "/" + (+month <= 9 ? "0" + month : month) + "/" + year;
      var timeValue = d.toLocaleString([], {
        hour: "2-digit",
        minute: "2-digit",
        hour12: true
      });
      const concatDateTime = dateValue + " " + timeValue;
      return concatDateTime;
    },
    fetch_time(val) {
      const d = new Date(parseInt(val * 1000));
      var timeValue = d.toLocaleString([], {
        hour: "2-digit",
        minute: "2-digit",
        hour12: true
      });
      return timeValue;
    },
    fetch_date(val) {
      const d = new Date(parseInt(val * 1000));
      var date = d.getDate().toLocaleString();
      var month = (d.getMonth() + 1).toLocaleString();
      var year = d.getFullYear();
      var dateValue = (+date <= 9 ? "0" + date : date) + "/" + (+month <= 9 ? "0" + month : month) + "/" + year;
      return dateValue;
    },
    async resume_action() {
      this.loading2 = true;
      try {
        let result = await API.graphql(graphqlOperation(claim_start_ticket, {
          input: {
            user_id: this.$store.getters.GetUserObj.user.user_id,
            ticket_id: this.rowInfo.ticket_id,
            assigned_id: this.rowInfo.assigned_id,
            action_type: "RESUME"
          }
        }));
        var response = JSON.parse(result.data.claim_start_ticket);
        if (response.Status == "SUCCESS") {
          this.loading2 = false;
          this.$emit("successMsg", response.Message);
        } else {
          this.$emit("errorMsg", response.Message);
        }
      } catch (error) {
        this.$emit("errorMsg", error.errors[0].message);
        this.loading2 = false;
      }
    }
  }
};
